@namespace sv_b7e5b26a0a794a4da8f3d84d92b1dab3.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section.Key == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                <span class="sidebar-icon">@section.Icon</span>
                <span class="sidebar-label">@section.Label</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

.settings-sidebar {
    width: 220px;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-radius: 6px;
    margin: 0.25rem 0.5rem;
    transition: background-color 0.15s;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar li.active {
    background-color: #e3f2fd;
    color: #1565c0;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.2rem;
}

.sidebar-label {
    font-size: 0.95rem;
}

