<div class="security-section">
    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="panel">
            <div class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <h3>Change Password</h3>
                <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
            </div>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPw">Current Password</label>
                        <input id="currentPw" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPw">New Password</label>
                        <input id="newPw" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPw">Confirm Password</label>
                        <input id="confirmPw" type="password" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <p class="error-message">@_passwordError</p>
                    }
                    @if (_passwordSuccess)
                    {
                        <p class="success-message">Password updated successfully!</p>
                    }
                    <button class="btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "●" : "○")
                </span>
                <span>@(_twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>Toggle 2FA</span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _sessions.FirstOrDefault())
                                {
                                    <button class="btn-danger-sm" @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn-danger" @onclick="RevokeSessionAsync">Revoke</button>
                        <button class="btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

