toolArgs.file_text:
.security-section {
    max-width: 700px;
}

.panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    cursor: pointer;
    background-color: #fafafa;
    border-radius: 6px;
}

.panel-header h3 {
    margin: 0;
}

.expand-icon {
    font-size: 0.85rem;
    color: #666;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.error-message {
    color: #c62828;
    font-size: 0.9rem;
}

.success-message {
    color: #2e7d32;
    font-size: 0.9rem;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.status-indicator {
    font-size: 1.5rem;
}

.status-indicator.enabled {
    color: #2e7d32;
}

.status-indicator.disabled {
    color: #9e9e9e;
}

.last-change {
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.5rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-left: 1rem;
    cursor: pointer;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    font-weight: 600;
    background-color: #fafafa;
}

.current-badge {
    font-size: 0.8rem;
    background-color: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
}

.btn-primary {
    background-color: #1565c0;
    color: #fff;
    border: none;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary:hover {
    background-color: #0d47a1;
}

.btn-secondary {
    background-color: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-danger-sm {
    background-color: #ef5350;
    color: #fff;
    border: none;
    padding: 0.3rem 0.7rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-danger-sm:hover {
    background-color: #c62828;
}

.btn-danger {
    background-color: #ef5350;
    color: #fff;
    border: none;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-danger:hover {
    background-color: #c62828;
}

.modal-overlay {
    position: fixed;
    inset: 0;
    background-color: rgba(0, 0, 0, 0.4);
    display: flex;
