arguments.file_text:
@namespace sv_b7e5b26a0a794a4da8f3d84d92b1dab3.Components.Pages.Settings
@using sv_b7e5b26a0a794a4da8f3d84d92b1dab3.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <h3>Theme</h3>
        <div class="radio-group">
            <label>
                <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = \"Light\"" />
                Light
            </label>
            <label>
                <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = \"Dark\"" />
                Dark
            </label>
            <label>
                <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = \"System\"" />
                System
            </label>
        </div>

        <h3>Font Size</h3>
        <div class="radio-group">
            <label>
                <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="() => _fontSize = \"Small\"" />
                Small
            </label>
            <label>
                <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="() => _fontSize = \"Medium\"" />
                Medium
            </label>
            <label>
                <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="() => _fontSize = \"Large\"" />
                Large
            </label>
        </div>

        <h3>Language</h3>
        <div class="form-group">
            <select @bind="_language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <h3>Compact Mode</h3>
        <label class="toggle-item">
            <input type="checkbox" @bind="_compactMode" />
            <span>Enable compact mode</span>
        </label>

        <!-- Live Preview -->
        <h3>Preview</h3>
        <div class="preview-area @GetPreviewClasses()">
            <p class="preview-title">Sample Content</p>
            <p>This is how your content will look with the selected settings.</p>
            <button class="preview-button">Example Button</button>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = _theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            _ => "preview-light"
        };
        var size = _fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium"
        };
        var compact = _compactMode ? "preview-compact" : "";
        return $"{theme} {size} {compact}";
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 600px;
}

.appearance-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.5rem;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.form-group select {
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

/* Live Preview */
.preview-area {
    margin-top: 0.75rem;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.2s;
}

.preview-area.preview-light {
    background-color: #ffffff;
    color: #333;
}

.preview-area.preview-dark {
    background-color: #1e1e1e;
    color: #e0e0e0;
}

.preview-area.preview-font-small {
    font-size: 0.8rem;
}

.preview-area.preview-font-medium {
    font-size: 1rem;
}

.preview-area.preview-font-large {
    font-size: 1.2rem;
}

.preview-area.preview-compact {
    padding: 0.6rem;
    line-height: 1.2;
}

.preview-title {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-button {
    margin-top: 0.5rem;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    background-color: #1565c0;
    color: #fff;
    border: none;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary:hover {
    background-color: #0d47a1;
}

.toast.success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background-color: #c8e6c9;
    color: #2e7d32;
    border-radius: 4px;
    font-weight: 500;
}

