    border-radius: 4px;
    cursor: pointer;
}

.btn-primary:hover {
    background-color: #0d47a1;
}

.toast.success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background-color: #c8e6c9;
    color: #2e7d32;
    border-radius: 4px;
    font-weight: 500;
}
