toolArgs.file_text:
@page "/settings"
@using sv_b7e5b26a0a794a4da8f3d84d92b1dab3.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        <h2>@GetSectionTitle()</h2>

        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "profile";

    private string GetSectionTitle() => _activeSection switch
    {
        "profile" => "Profile",
        "notifications" => "Notifications",
        "security" => "Security",
        "appearance" => "Appearance",
        _ => "Settings"
    };
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 80px);
    background-color: #fff;
    border-radius: 8px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
    margin: 1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #212121;
}

